INSERT INTO acteurs (code, nom, role, domiciliation, est_depositaire_tiers, alias, payload, provenance, confiance) VALUES ('de_pury_pictet', 'de Pury Pictet Turrettini', 'gerant', 'BE', false, ARRAY['de Pury Pictet Turrettini (Belgique)', 'de Pury Pictet Turrettini', 'De Pury Pictet']::text[], '{"libelle_affichage": "De Pury Pictet", "convention": "Écrire « De Pury Pictet ». Jamais « PPT », jamais le nom complet avec Turrettini.", "source": "relevé Interagyr — pied de page présent sur 100 % des pages"}'::jsonb, 'seed', 'high') ON CONFLICT (code) DO UPDATE SET nom=EXCLUDED.nom, role=EXCLUDED.role, domiciliation=EXCLUDED.domiciliation, est_depositaire_tiers=EXCLUDED.est_depositaire_tiers, alias=EXCLUDED.alias, payload=EXCLUDED.payload, confiance=EXCLUDED.confiance, version=acteurs.version+1;
