INSERT INTO acteurs (code, nom, role, domiciliation, est_depositaire_tiers, alias, payload, provenance, confiance) VALUES ('spirica', 'Spirica', 'assureur', 'FR', false, ARRAY['SPIRICA', 'Spirica']::text[], '{"note": "Émetteur réel des relevés distribués sous la marque UAF Life Patrimoine. Émetteur ≠ distributeur (D24).", "source": "relevés « UAF » Cerise et Pollux — mentions légales SPIRICA"}'::jsonb, 'seed', 'high') ON CONFLICT (code) DO UPDATE SET nom=EXCLUDED.nom, role=EXCLUDED.role, domiciliation=EXCLUDED.domiciliation, est_depositaire_tiers=EXCLUDED.est_depositaire_tiers, alias=EXCLUDED.alias, payload=EXCLUDED.payload, confiance=EXCLUDED.confiance, version=acteurs.version+1;
INSERT INTO acteurs (code, nom, role, domiciliation, est_depositaire_tiers, alias, payload, provenance, confiance) VALUES ('uaf_life_patrimoine', 'UAF Life Patrimoine', 'plateforme', 'FR', false, ARRAY['UAF LIFE PATRIMOINE', 'UAF Life Patrimoine', 'UAF']::text[], '{"note": "Distributeur, PAS l''émetteur du relevé. Les relevés nommés « UAF » sont émis par Spirica.", "emetteurs_associes": ["spirica"]}'::jsonb, 'seed', 'high') ON CONFLICT (code) DO UPDATE SET nom=EXCLUDED.nom, role=EXCLUDED.role, domiciliation=EXCLUDED.domiciliation, est_depositaire_tiers=EXCLUDED.est_depositaire_tiers, alias=EXCLUDED.alias, payload=EXCLUDED.payload, confiance=EXCLUDED.confiance, version=acteurs.version+1;
INSERT INTO acteurs (code, nom, role, domiciliation, est_depositaire_tiers, alias, payload, provenance, confiance) VALUES ('nortia', 'Nortia', 'plateforme', 'FR', false, ARRAY['Nortia']::text[], '{"note": "Plateforme grossiste, PAS un assureur. Son nom n''apparaît NULLE PART dans le texte du relevé : l''identité est portée par un logo image. Nommé par un humain, jamais déduit au runtime (D24/N7).", "identifie_par": "logo image, non OCR — le nom de fichier ne fait pas foi", "source": "relevé « Nortia 30 06 26 »"}'::jsonb, 'seed', 'medium') ON CONFLICT (code) DO UPDATE SET nom=EXCLUDED.nom, role=EXCLUDED.role, domiciliation=EXCLUDED.domiciliation, est_depositaire_tiers=EXCLUDED.est_depositaire_tiers, alias=EXCLUDED.alias, payload=EXCLUDED.payload, confiance=EXCLUDED.confiance, version=acteurs.version+1;
INSERT INTO acteurs (code, nom, role, domiciliation, est_depositaire_tiers, alias, payload, provenance, confiance) VALUES ('himalia_emetteur_a_confirmer', 'Émetteur du contrat HIMALIA CAPITALISATION (à confirmer)', 'assureur', NULL, false, ARRAY['HIMALIA CAPITALISATION', 'Himalia Capi']::text[], '{"note": "L''assureur n''est identifiable NI dans le texte NI par une source fiable de ce run. Un nom plausible circule mais n''est pas vérifié : il n''est pas inscrit ici. À faire nommer par le CGP (AskUser), au même titre que K7.", "question_ouverte": "Quel assureur porte la gamme HIMALIA CAPITALISATION ?", "identifie_par": "logo image, non OCR"}'::jsonb, 'seed', 'low') ON CONFLICT (code) DO UPDATE SET nom=EXCLUDED.nom, role=EXCLUDED.role, domiciliation=EXCLUDED.domiciliation, est_depositaire_tiers=EXCLUDED.est_depositaire_tiers, alias=EXCLUDED.alias, payload=EXCLUDED.payload, confiance=EXCLUDED.confiance, version=acteurs.version+1;
INSERT INTO acteurs (code, nom, role, domiciliation, est_depositaire_tiers, alias, payload, provenance, confiance) VALUES ('wealins', 'WEALINS S.A.', 'assureur', 'LU', false, ARRAY['WEALINS S.A.', 'Wealins', 'Wealins Capi France']::text[], '{"rcs": "Luxembourg B 53682", "tva": "LU 166 094 20", "adresse": "12 rue Léon Laval, L-3372 Leudelange", "note": "Assurance-vie luxembourgeoise : le triangle de sécurité impose un dépositaire tiers nommé par fonds dédié (FID). Un contrat peut donc porter PLUSIEURS dépositaires, et ils changent dans le temps (voir successions).", "source": "relevés annuels FC051727 et FC055211"}'::jsonb, 'seed', 'high') ON CONFLICT (code) DO UPDATE SET nom=EXCLUDED.nom, role=EXCLUDED.role, domiciliation=EXCLUDED.domiciliation, est_depositaire_tiers=EXCLUDED.est_depositaire_tiers, alias=EXCLUDED.alias, payload=EXCLUDED.payload, confiance=EXCLUDED.confiance, version=acteurs.version+1;
INSERT INTO acteurs (code, nom, role, domiciliation, est_depositaire_tiers, alias, payload, provenance, confiance) VALUES ('cardif', 'Cardif Assurance Vie', 'assureur', 'FR', false, ARRAY['Cardif Assurance Vie', 'BNP Paribas Cardif', 'Cardif']::text[], '{"note": "Contrat FR : pas de dépositaire tiers, la colonne dépositaire vaut NC par convention réglementaire — « non communicable », pas « non renseigné » (D26).", "reseau_declare": "DIRECT-CGPI", "source": "relevé Cardif Elite Capitalisation Personnes Morales"}'::jsonb, 'seed', 'high') ON CONFLICT (code) DO UPDATE SET nom=EXCLUDED.nom, role=EXCLUDED.role, domiciliation=EXCLUDED.domiciliation, est_depositaire_tiers=EXCLUDED.est_depositaire_tiers, alias=EXCLUDED.alias, payload=EXCLUDED.payload, confiance=EXCLUDED.confiance, version=acteurs.version+1;
