INSERT INTO acteurs (code, nom, role, domiciliation, est_depositaire_tiers, alias, payload, provenance, confiance) VALUES ('ca_indosuez', 'CA Indosuez', 'depositaire', NULL, true, ARRAY['CA Indosuez', 'Indosuez', 'Crédit Agricole Indosuez']::text[], '{"note": "Dépositaire d''un FID Wealins. Successeur d''Intesa sur la poche FAS du contrat FC051727.", "question_ouverte": "K7 — CA Indosuez et Banque Thaler sont-ils la même entité, ou deux repreneurs distincts de la poche ex-Intesa ? Le salvage ne permet pas de trancher. AskUser au CGP."}'::jsonb, 'seed', 'medium') ON CONFLICT (code) DO UPDATE SET nom=EXCLUDED.nom, role=EXCLUDED.role, domiciliation=EXCLUDED.domiciliation, est_depositaire_tiers=EXCLUDED.est_depositaire_tiers, alias=EXCLUDED.alias, payload=EXCLUDED.payload, confiance=EXCLUDED.confiance, version=acteurs.version+1;
