INSERT INTO acteur_successions (predecesseur_code, successeur_code, date_effet, date_cloture, contexte, payload, provenance, confiance) VALUES ('intesa_sanpaolo', 'ca_indosuez', NULL, NULL, 'Wealins FC051727 — poche FAS', '{"note": "Date d''effet non établie par le relevé : laissée à null plutôt que devinée. Une note intermédiaire du run Gronier mentionnait « Thaler/Indosuez » sans permettre de trancher — voir K7.", "question_ouverte": "K7 — le successeur est-il CA Indosuez, Banque Thaler, ou les deux successivement ?", "reperes_chiffres": "Base au 31/12/2024 retenue à 550 568 € dans la version officielle post-relevés ; versement dédié de 250 000 € le 13/03/2025."}'::jsonb, 'seed', 'low');
INSERT INTO acteur_successions (predecesseur_code, successeur_code, date_effet, date_cloture, contexte, payload, provenance, confiance) VALUES ('cic', 'quintet', NULL, '2025-12-30', 'Wealins FC051727 — poche FID', '{"note": "Clôture au 30/12/2025, précision obtenue seulement après lecture des relevés officiels (elle ne figurait pas dans l''Excel de suivi). Date d''effet du changement non établie : laissée à null.", "reperes_chiffres": "Base au 31/12/2024 retenue à 446 933 € dans la version officielle ; versement dédié de 200 000 € le 07/05/2025.", "ecart_de_source": "L''Excel « Catégories & Perf » portait un versement de 251 627 € qui n''existe dans aucun relevé officiel — donnée erronée de la source Excel, corrigée. Illustration de la hiérarchie de sources : le relevé prime."}'::jsonb, 'seed', 'medium');
INSERT INTO gabarits (emetteur_code, gabarit, periodicite, template_id_natif, signature, n_pages_indicatif, extraction_hints, champs_publies, invariant_controle, emetteur_lisible, provenance, confiance) VALUES ('de_pury_pictet', 'evaluation_portefeuille_mandat', 'a_la_demande', NULL, '{"metadata_pdf": {"producer": "Microsoft Reporting Services", "creator": "Microsoft Reporting Services"}, "ancres_texte": ["de Pury Pictet Turrettini (Belgique)", "Aperçu du Portefeuille", "Point de Contact", "Matrice allocation actifs et devises", "Détail des Positions - Liquidités", "Liste des transactions", "Dividendes, intérêts et autres paiements", "Adéquation du profil", "En cas de divergence avec l''estimation produite par la banque dépositaire, les indications de cette dernière prévaudront"], "marqueurs_structure": ["Séquence fixe de 12 titres de section, dans l''ordre", "Pied de page sur chaque page : émetteur + « Situation au JJ/MM/AAAA » + « Page X/N »", "En-têtes des tableaux de positions sur 2 lignes, sous-colonnes Devise/EUR sous RESULTAT et EVALUATION", "Motif « Total : [sous-catégorie] » après chaque groupe d''instruments", "Page de garde en 2 colonnes à libellés fixes (Compte / Devise de référence / Situation au / Etablie au / Banque Dépositaire / Profil / Mode de détention | Gérant / Tél / E-mail)"], "token_periodicite": null}'::jsonb, '9-14', '{"pieges": ["DEUX conventions numériques dans le MÊME document : le bloc Résumé est anglo-saxon (1,925,477 / 97.15%), tout le reste est franco-suisse (1 134 708,36 / 25,19%). Un parseur réglé sur un seul séparateur casse sur l''autre bloc. Cette hétérogénéité est stable : elle vient de sous-rapports RDL distincts, c''est donc aussi un marqueur.", "Chaque position est étalée sur 2 lignes physiques : ligne 1 = valeurs, ligne 2 = ISIN + prix d''achat moyen + un second pourcentage sans libellé. Recoupler avant parsing, sinon l''ISIN est perdu.", "Colonne « RESULTAT YTD » : deux pourcentages empilés. Le bon est la 2e ligne (résultat depuis achat), en EUR.", "Fonds monétaires classés à tort « Obligations » → reclasser en monetaire.", "Deux niveaux de totaux : total de section ET sous-totaux « Total : ». Double comptage si on somme les deux.", "Deux sections sont purement graphiques (Evolution des actifs, Exposition actions) : le texte s''arrête après le titre. Ce n''est PAS un échec d''extraction.", "« Rendement benchmark * » affiche un « % » seul sans chiffre pour les mois sans historique.", "Deux dates proches à ne pas confondre : « Situation au » (arrêté) et « Etablie au » (édition).", "La composition du benchmark dépend du profil client : apparence de boilerplate, réalité volatile. À exclure de la signature."], "ancrage_tableaux": ["Pas de filets de tableau : pdftotext -layout impératif.", "Fusionner les 2 lignes d''en-tête avant tout parsing positionnel."], "format_numerique": {"milliers": "espace (bloc principal) / virgule (bloc Résumé)", "decimal": "virgule (principal) / point (Résumé)"}}'::jsonb, '{"perf_par_ligne": "oui", "forme": "Colonne « RESULTAT YTD », 2e ligne = résultat depuis achat, en EUR.", "horizon": "depuis achat"}'::jsonb, 'Σ sous-totaux « Total : » par catégorie = total de section ; Σ sections = total portefeuille.', true, 'seed', 'high') ON CONFLICT (emetteur_code, gabarit, periodicite) DO UPDATE SET template_id_natif=EXCLUDED.template_id_natif, signature=EXCLUDED.signature, n_pages_indicatif=EXCLUDED.n_pages_indicatif, extraction_hints=EXCLUDED.extraction_hints, champs_publies=EXCLUDED.champs_publies, invariant_controle=EXCLUDED.invariant_controle, emetteur_lisible=EXCLUDED.emetteur_lisible, confiance=EXCLUDED.confiance, version=gabarits.version+1;
INSERT INTO gabarits (emetteur_code, gabarit, periodicite, template_id_natif, signature, n_pages_indicatif, extraction_hints, champs_publies, invariant_controle, emetteur_lisible, provenance, confiance) VALUES ('dauphine_am', 'reporting_hebdo_mandat', 'hebdomadaire', NULL, '{"metadata_pdf": {"producer": "Microsoft Word", "creator": "Microsoft Word"}, "ancres_texte": ["Reporting hebdomadaire", "Composition du portefeuille & mouvements de la semaine", "Détail des positions", "Mouvements de la semaine", "Dauphine AM, filiale de Rhétorès Groupe", "agrément AMF n°GP-17000033", "Des convictions au service de la gestion de vos actifs", "COMMUNICATION À CARACTÈRE NON COMMERCIAL", "NE PEUT ÊTRE TRANSMIS À DES CLIENTS FINAUX"], "marqueurs_structure": ["En-tête de colonnes exact : ISIN SUPPORT VALEUR +/- VALUE +/- % POIDS", "En-tête courant « Reporting hebdomadaire — Semaine du … au … » à partir de la page 2", "Pied de page « Document à caractère non commercial — non contractuel · Dauphine AM · agrément AMF n°GP-17000033 » + « Page N », absent de la page 1", "Filigrane fragmenté en 9 jetons identiques et ordonnés sur chaque page : U clu / sa s / ex / ge ive / in e / te n / rn t / m / e", "Hiérarchie catégorie > lignes > sous-total > « Total portefeuille »"], "token_periodicite": "Semaine du"}'::jsonb, '3-6', '{"pieges": ["Le filigrane diagonal se fragmente en 9 jetons parasites insérés au milieu du contenu en mode -layout. Les filtrer AVANT tout parsing. Ils sont identiques et ordonnés : donc aussi une ancre fiable.", "La colonne « +/- % » est la variation DE LA SEMAINE, pas un YTD. Le YTD n''existe que dans le bloc KPI.", "Noms de SUPPORT repliés sur 2 lignes, valeurs sur la première : désalignement si parsing naïf.", "Sous-totaux de classe sans ISIN ni SUPPORT (4 champs au lieu de 6) : les distinguer par l''absence d''ISIN.", "Ligne LIQUIDITÉS : tiret cadratin « — » pour +/- VALUE et +/- % = non applicable, PAS zéro.", "Signe moins Unicode U+2212, pas le tiret ASCII.", "Le tableau des positions est scindé entre deux pages SANS ré-émission de l''en-tête.", "La valorisation apparaît deux fois (« VALORISATION AU » en garde, « VALORISATION TOTALE » en KPI) : dédupliquer.", "Les libellés de poches KPI varient selon le mandat (ACTIONS vs OBLIGATIONS/MONÉTAIRE) : c''est du volatil, pas un drift.", "Section Mouvements parfois vide : « Aucun mouvement sur la semaine. »", "La section ACTUALITÉS est optionnelle (présente si des valeurs sont commentées) : son absence n''est pas un drift.", "Nom de fichier en Unicode NFD (accent décomposé) : résoudre par glob, ne jamais retaper le chemin."], "ancrage_tableaux": ["Pas de filets : -layout impératif.", "Fusionner les libellés de support repliés avant association aux valeurs."], "format_numerique": {"milliers": "espace insécable", "decimal": "virgule", "negatif": "U+2212"}}'::jsonb, '{"perf_par_ligne": "oui", "forme": "Colonne « +/- % » du détail des positions.", "horizon": "hebdomadaire — à préciser dans validation_note, ne jamais confondre avec un YTD"}'::jsonb, 'Σ sous-totaux de classes = « Total portefeuille » (vérifié au € près). Le KPI « NOMBRE DE LIGNES » approche le compte des lignes extraites, mais sa convention d''inclusion des liquidités n''est pas garantie.', true, 'seed', 'high') ON CONFLICT (emetteur_code, gabarit, periodicite) DO UPDATE SET template_id_natif=EXCLUDED.template_id_natif, signature=EXCLUDED.signature, n_pages_indicatif=EXCLUDED.n_pages_indicatif, extraction_hints=EXCLUDED.extraction_hints, champs_publies=EXCLUDED.champs_publies, invariant_controle=EXCLUDED.invariant_controle, emetteur_lisible=EXCLUDED.emetteur_lisible, confiance=EXCLUDED.confiance, version=gabarits.version+1;
INSERT INTO gabarits (emetteur_code, gabarit, periodicite, template_id_natif, signature, n_pages_indicatif, extraction_hints, champs_publies, invariant_controle, emetteur_lisible, provenance, confiance) VALUES ('spirica', 'releve_situation_av', 'a_la_demande', NULL, '{"metadata_pdf": {"creator": "JasperReports Library", "producer": "OpenPDF"}, "ancres_texte": ["Objet : Relevé de Situation", "SITUATION AU", "Montant de la valeur atteinte au", "Valeur de rachat*", "Le Relevé de Situation n''engage en rien la responsabilité de SPIRICA.", "Ce document n''a pas de valeur contractuelle.", "Vos interlocuteurs à votre service :", "Le rachat est l''opération par laquelle vous demandez"], "marqueurs_structure": ["Bandeau titre centré « SITUATION AU [date] » séparant le corps de lettre du tableau", "En-tête de la page 2 = « Contrat n° [numéro] » seul", "Pied de page identique : « Page X / Y » + 3 lignes de disclaimer SPIRICA", "Bloc final en 3 paires libellé:valeur (Votre conseiller / Adresse / Téléphone)"], "token_periodicite": null}'::jsonb, '>=2', '{"pieges": ["ATTENTION metadata : JasperReports apparaît AUSSI chez l''émetteur Himalia. La couche 1 ne discrimine pas seule.", "Sans -layout, le flux sépare tous les en-têtes de colonnes de toutes les valeurs : reconstruction impossible sans coordonnées.", "Deux libellés de colonnes contiennent la DATE d''arrêté (« Nombre de parts au 31/12/2022 », « Valeur atteinte au … en euros ») : matcher par motif tolérant, jamais par chaîne exacte.", "Deux dates très éloignées : arrêté et date d''édition du courrier. Un exemplaire observé est une réédition de 2026 pour un arrêté de 2022. Seule « SITUATION AU » fait foi.", "Cellule « Nombre de parts » VIDE pour un fonds euros : normal, pas un décalage de colonne.", "« Montant de la valeur atteinte » et « Valeur de rachat » sont égaux dans les exemplaires vus, mais peuvent diverger (pénalités) : ne pas présumer l''égalité.", "Aucun ISIN : identification des supports par libellé seul, donc référentiel externe nom→ISIN nécessaire.", "La civilité varie et modifie les accords des phrases boilerplate : normaliser avant ancrage.", "Un seul support dans les exemplaires vus (100 %) : le profil doit rester valide de 0 à N lignes et pour d''autres modes de gestion que « Gestion libre »."], "ancrage_tableaux": ["Extraction par coordonnées (-layout) obligatoire.", "Le sous-titre de mode de gestion précède le tableau."], "format_numerique": {"milliers": "espace insécable", "decimal": "virgule"}}'::jsonb, '{"perf_par_ligne": "oui", "forme": "Format « PRM ».", "horizon": "à confirmer sur un exemplaire multi-support"}'::jsonb, 'Σ colonne % = 100 ; Σ valeurs atteintes des lignes = « Montant de la valeur atteinte ».', true, 'seed', 'high') ON CONFLICT (emetteur_code, gabarit, periodicite) DO UPDATE SET template_id_natif=EXCLUDED.template_id_natif, signature=EXCLUDED.signature, n_pages_indicatif=EXCLUDED.n_pages_indicatif, extraction_hints=EXCLUDED.extraction_hints, champs_publies=EXCLUDED.champs_publies, invariant_controle=EXCLUDED.invariant_controle, emetteur_lisible=EXCLUDED.emetteur_lisible, confiance=EXCLUDED.confiance, version=gabarits.version+1;
INSERT INTO gabarits (emetteur_code, gabarit, periodicite, template_id_natif, signature, n_pages_indicatif, extraction_hints, champs_publies, invariant_controle, emetteur_lisible, provenance, confiance) VALUES ('nortia', 'releve_portefeuille_cto', 'mensuel', NULL, '{"metadata_pdf": {"note": "Polices standard non embarquées (Courier/Helvetica), pas de producteur distinctif."}, "ancres_texte": ["RELEVE PORTEFEUILLE AU", "VOTRE COMPTE TITRES", "VALORISATION EN : EUR", "Code et désignation valeur", "Prix moyen d''acquisition (PMA)", "TITRES - EUROPE", "Total du portefeuille", "INFORMATIONS FISCALES SUR VOTRE PORTEFEUILLE DEPUIS le 1er Janvier", "Instrument financier éligible à la règlementation MIF", "Dépôt à l''étranger"], "marqueurs_structure": ["Marqueur technique « ^{PSTOCK=paper_0} » en toute première ligne de CHAQUE page : invisible à l''écran, très fiable", "En-tête complet répété sur chaque page (titre + date d''édition + pagination + adresse + conseiller + n° de compte)", "En-tête de tableau à 7 colonnes réparti sur 2-3 lignes physiques", "Macro-zones dans l''ordre fixe : TITRES - EUROPE, TITRES - INTERNATIONAL, TITRES - AUTRES, LIQUIDITES", "La dernière page porte toujours « Total du portefeuille » puis le bloc INFORMATIONS FISCALES"], "token_periodicite": "édité le 7 du mois suivant l''arrêté (indice, à confirmer)"}'::jsonb, 'variable', '{"pieges": ["Émetteur NON lisible en texte : le mot « Nortia » n''apparaît nulle part, l''identité est portée par un logo image. L''identification passe par la signature, jamais par le nom de fichier (D24/N7).", "Le flag « E » (dépôt à l''étranger) est une colonne fantôme sans position X fixe : en extraction il se décale loin de sa ligne d''origine.", "Les sous-totaux de catégorie n''ont que 3 champs (catégorie / % / montant) contre 7 pour les lignes titres : un parseur à nombre de colonnes fixe casse.", "Les négatifs s''écrivent « - 29 220,00 » avec un ESPACE après le signe : risque de découpage en deux jetons.", "« EUR » n''est accolé qu''à la colonne Cours, implicite ailleurs.", "La précision décimale de Quantité varie selon la nature du titre (0 à 4 décimales) : ce n''est pas un discriminant de colonne.", "La page 2 réaffiche tout l''en-tête mais ne contient QUE « Total du portefeuille » : une nouvelle page n''implique pas de nouvelles lignes.", "Σ des % de sections = 100 seulement EN INCLUANT LIQUIDITES : un parseur qui ignore les libellés hors « TITRES - » sous-estime fortement l''actif.", "Le marqueur ^{PSTOCK} pollue le texte extrait : filtrer avant matching, garder pour la signature."], "ancrage_tableaux": ["Pas de filets : le regroupement repose sur l''indentation et la présence/absence de « % »."], "format_numerique": {"milliers": "espace", "decimal": "virgule", "negatif": "signe moins suivi d''un espace"}}'::jsonb, '{"perf_par_ligne": "derivable", "forme": "Plus-value en EUROS (colonne « Plus ou moins value latente »), pas en %. Le % se dérive du gain rapporté au PMA.", "horizon": "latent, depuis acquisition"}'::jsonb, 'Σ % des sections, liquidités incluses = 100,00 ; Σ valorisations = « Total du portefeuille ».', false, 'seed', 'medium') ON CONFLICT (emetteur_code, gabarit, periodicite) DO UPDATE SET template_id_natif=EXCLUDED.template_id_natif, signature=EXCLUDED.signature, n_pages_indicatif=EXCLUDED.n_pages_indicatif, extraction_hints=EXCLUDED.extraction_hints, champs_publies=EXCLUDED.champs_publies, invariant_controle=EXCLUDED.invariant_controle, emetteur_lisible=EXCLUDED.emetteur_lisible, confiance=EXCLUDED.confiance, version=gabarits.version+1;
INSERT INTO gabarits (emetteur_code, gabarit, periodicite, template_id_natif, signature, n_pages_indicatif, extraction_hints, champs_publies, invariant_controle, emetteur_lisible, provenance, confiance) VALUES ('himalia_emetteur_a_confirmer', 'releve_situation_capi', 'annuel', NULL, '{"metadata_pdf": {"creator": "JasperReports", "producer": "iText 2.1.7 by 1T3XT"}, "ancres_texte": ["Relevé de situation au", "Ce document n''est pas assimilable à un état de situation.", "Total versé depuis l''origine", "Total investi depuis l''origine", "Epargne atteinte au", "Répartition de l''investissement", "Plus/moins-values***", "Prix d''Achat Moyen", "Le montant de l''épargne atteinte est obtenu à partir des dernières valeurs connues.", "Point d''attention :"], "marqueurs_structure": ["Titre de page « Répartition » répété sur chaque page du tableau", "DEUX groupes de colonnes aux libellés HOMONYMES : « Montant(€) » et « %** » apparaissent sous « Répartition de l''investissement » ET sous « Plus/moins-values*** »", "Aucune ligne Total dans le tableau : le total n''existe qu''en bloc d''en-tête page 1", "Bloc de 3 notes (*)(**)(***) suivi de « Point d''attention : »"], "token_periodicite": "arrêté au 31/12 (indice faible — périodicité à confirmer sur un second exemplaire)"}'::jsonb, '1 page de synthèse + N pages de tableau', '{"pieges": ["Émetteur NON lisible en texte : identité portée par un logo image. À faire nommer par le CGP.", "ATTENTION metadata : JasperReports apparaît AUSSI chez Spirica. La couche 1 ne discrimine pas seule — c''est ici que les ancres texte font tout le travail.", "Colonnes HOMONYMES sous deux groupes parents différents : lire par nom de colonne seul est ambigu, il faut le groupe.", "Sans -layout, le flux réordonne tout par colonne : une valeur isolée atterrit APRÈS les notes de bas de page.", "La colonne %** des plus/moins-values est VIDE quand le Prix d''Achat Moyen vaut 0,00 € : un parseur à nombre de jetons fixe échoue.", "AUCUNE ligne Total dans le tableau : le total doit être RECALCULÉ. Vérifié : Σ des 9 lignes = « Epargne atteinte » au centime.", "La catégorie « Fonds UC » n''est affichée qu''une fois, en tête de la première page du tableau, et n''est PAS répétée : perte de contexte en traitement page par page.", "Noms de supports repliés sur 2 lignes : fusionner avant association aux valeurs.", "Le symbole € est explicite dans les cellules PAM, implicite dans « Montant(€) ».", "Aucun ISIN : référentiel externe nom→ISIN nécessaire.", "Aucune pagination dans le texte : la position ne s''obtient que par pdfinfo.", "Σ %** ≈ 99,99 à cause des arrondis : ne JAMAIS exiger 100,00 strict.", "Prévoir une catégorie « Fonds Euros » en plus de « Fonds UC » : non observée mais plausible."], "ancrage_tableaux": ["-layout impératif.", "Désambiguïser les colonnes homonymes par leur groupe parent."], "format_numerique": {"milliers": "espace insécable", "decimal": "virgule"}}'::jsonb, '{"perf_par_ligne": "oui", "forme": "Format « PRM ». Plus/moins-values en montant ET en %, sous le second groupe de colonnes.", "horizon": "depuis acquisition (base Prix d''Achat Moyen)"}'::jsonb, 'Σ « Montant(€) » du groupe Répartition = « Epargne atteinte au [date] » du bloc page 1 — vérifié exact. Σ %** ≈ 100 à l''arrondi près, jamais strict.', false, 'seed', 'medium') ON CONFLICT (emetteur_code, gabarit, periodicite) DO UPDATE SET template_id_natif=EXCLUDED.template_id_natif, signature=EXCLUDED.signature, n_pages_indicatif=EXCLUDED.n_pages_indicatif, extraction_hints=EXCLUDED.extraction_hints, champs_publies=EXCLUDED.champs_publies, invariant_controle=EXCLUDED.invariant_controle, emetteur_lisible=EXCLUDED.emetteur_lisible, confiance=EXCLUDED.confiance, version=gabarits.version+1;
INSERT INTO gabarits (emetteur_code, gabarit, periodicite, template_id_natif, signature, n_pages_indicatif, extraction_hints, champs_publies, invariant_controle, emetteur_lisible, provenance, confiance) VALUES ('wealins', 'releve_annuel_capi_lux', 'annuel', NULL, '{"metadata_pdf": {"note": "Le marqueur fort est structurel, pas dans les métadonnées : paginations locales multiples."}, "ancres_texte": ["Wealins Capi France", "Contrat de capitalisation", "Caractéristiques du contrat", "Information sur l''évolution du contrat", "Arbitrages et/ou changement de banque dépositaire", "Informations relatives aux unités de compte", "Aperçu des fonds", "Profil d''investissement", "Valeur totale du fonds au", "R.C.S.: Luxembourg B 53682", "TVA Intra-com.: LU 166 094 20", "wealins.com"], "marqueurs_structure": ["Paginations LOCALES multiples et non contiguës : aucune pagination globale n''existe", "Footer légal WEALINS identique au caractère près sur presque toutes les pages", "Bloc structurel répété PAR FID dans l''annexe", "En-tête d''annexe « INFORMATION ANNUELLE : [date] - [contrat] » + « Fonds : [nom] »"], "token_periodicite": "INFORMATION ANNUELLE"}'::jsonb, '15-26 selon le nombre de FID — HORS matching', '{"pieges": ["Le document est la concaténation de 4 sous-templates : ne JAMAIS segmenter par une pagination globale, elle n''existe pas.", "AMBIGUÏTÉ DATE / PAGINATION : le motif « \\d+/\\d+ » attrape des dates (27/01, 31/12, 13/03) avant la vraie pagination. Ancrer la pagination du corps sur un dénominateur petit et constant (n/N avec N ≤ 12), et l''annexe sur le préfixe littéral « Page ».", "Le mot « Fonds » a TROIS sens : le FID (enveloppe), une catégorie d''actif, et le titre du sous-tableau des lignes OPC. Un grep naïf est inexploitable.", "Deux tableaux « Situation au » quasi identiques (N-1 et N) : capturer la date DU TITRE avec le tableau.", "« Type d''Actifs » apparaît deux fois avec des contenus différents : désambiguïser par le contexte, pas par le titre.", "Le détail « Fonds » s''étale sur plusieurs pages sans sous-total intermédiaire : concaténer avant d''agréger.", "Trois niveaux de totaux par FID : hiérarchiser, sinon double comptage.", "Séparateur de milliers INCOHÉRENT entre le corps (points : 1.014.646,31) et l''annexe (espaces : 545 975,50), dans le même document.", "La colonne « Année » du rendement n''est PAS la somme des trimestres (rendements composés) : ne jamais valider par addition.", "Ligne « Open Cost Order » négative dans les liquidités : c''est un débit en attente, pas un actif.", "Le nom du FID ressemble au nom de la banque dépositaire (« 540709 Banque Thaler SA ») : ne pas confondre identifiant produit et tiers dépositaire.", "L''artefact « <booklet> » apparaît en texte brut : le filtrer du contenu, le GARDER comme frontière de segment.", "Le code agence en tête de courrier peut être pris à tort pour un numéro de contrat."], "ancrage_tableaux": ["-layout impératif.", "En-têtes empilés sur 2-3 lignes au-dessus de valeurs situées plus bas : désalignement vertical à corriger."], "format_numerique": {"milliers": "point (corps) / espace (annexe)", "decimal": "virgule", "negatif": "signe moins suivi d''un espace"}, "segments": {"_note": "Décision O11 : UN profil composite, avec segments déclarés. Un seul appariement (peu coûteux, aucune couche de matching supplémentaire), mais le DRIFT est évalué PAR SEGMENT — donc une évolution de la seule page Loi Pacte ne remet pas en cause tout le profil et produit une proposition de mise_a_jour ciblée. Justification empirique : les frontières sont détectables au caractère près et se sont vérifiées identiques sur deux exemplaires de tailles très différentes (26 p./2 FID et 15 p./1 FID). Et la page Loi Pacte porte un pied de page DIFFÉRENT (autre numéro de fax), preuve qu''elle est produite par un autre générateur — donc de cycles de vie indépendants.", "liste": [{"cle": "adresse", "role": "page d''adresse pour fenêtre d''enveloppe", "frontiere": "première page ; ni pagination ni pied de page légal", "extraire": false}, {"cle": "corps_reglementaire", "role": "caractéristiques du contrat, évolution, situations N-1 et N, valeur de rachat, primes, rachats, arbitrages, frais", "frontiere": "pied de page fax-A + pagination locale « n/N » (N petit et constant, ex. 4/4 ou 6/6)", "extraire": true, "note": "Longueur variable selon le nombre de FID (5 pages à 1 FID, 7 pages à 2 FID)."}, {"cle": "loi_pacte", "role": "tableau réglementaire de performance brute/nette, frais et rétrocessions", "frontiere": "EXACTEMENT une page, identifiable par un pied de page au numéro de fax DIFFÉRENT et par l''ABSENCE de pagination", "extraire": true, "note": "Segment le plus susceptible d''évoluer seul, la source étant réglementaire. C''est ce qui justifie le drift par segment."}, {"cle": "annexe_booklet", "role": "look-through par fonds interne dédié : type d''actifs, rendement trimestriel, frais, détail des lignes OPC, fonds alternatifs, liquidités", "frontiere": "début marqué par l''artefact « <booklet> » ; pages numérotées « Page n / M » où M s''auto-déclare", "extraire": true, "note": "Longueur proportionnelle au nombre de FID et de lignes OPC. Bloc structurel répété par FID."}]}}'::jsonb, '{"perf_par_ligne": "par_poche", "forme": "Aucune performance par ligne. Rendement publié PAR FID, en trimestres + année. Le tableau Loi Pacte donne une performance brute/nette par fonds, souvent « non disponible ».", "horizon": "trimestriel et annuel, par fonds dédié"}'::jsonb, 'Par FID : Σ (sous-total Fonds + sous-total Fonds alternatifs + sous-total Liquidités) = « Valeur totale du fonds ». Σ des FID = valeur du contrat. Ne jamais contrôler le rendement annuel par addition des trimestres.', true, 'seed', 'high') ON CONFLICT (emetteur_code, gabarit, periodicite) DO UPDATE SET template_id_natif=EXCLUDED.template_id_natif, signature=EXCLUDED.signature, n_pages_indicatif=EXCLUDED.n_pages_indicatif, extraction_hints=EXCLUDED.extraction_hints, champs_publies=EXCLUDED.champs_publies, invariant_controle=EXCLUDED.invariant_controle, emetteur_lisible=EXCLUDED.emetteur_lisible, confiance=EXCLUDED.confiance, version=gabarits.version+1;
INSERT INTO gabarits (emetteur_code, gabarit, periodicite, template_id_natif, signature, n_pages_indicatif, extraction_hints, champs_publies, invariant_controle, emetteur_lisible, provenance, confiance) VALUES ('cardif', 'situation_contrat_capi_pm', 'annuel', 'TYPE_MODELE=66 · MODELE=Relevé situation front-office', '{"metadata_pdf": {"producer": "Apache FOP", "creator": "BdocPDF"}, "ancres_texte": ["Cardif Elite Capitalisation Personnes Morales", "Contrat de capitalisation", "Cumul des opérations pour l''année", "Situation du contrat au", "Garanties au terme du contrat", "Valeur du contrat au", "(1) Net de frais de gestion."], "marqueurs_structure": ["Bloc technique XML embarqué, répété identique en bas de CHAQUE page : <PAPIER> / <TYPE_ENVOI> / <MODELE> / <TYPE_MODELE> / <RESEAU>", "En-tête de colonnes : Support | Code ISIN | Répartition | Nombre d''unités de compte | Valeur de l''unité de compte | Valorisation", "Sous-titre de groupe « Gestion libre » portant le total du groupe sur sa propre ligne", "Ligne « FONDS GENERAL (1) » avec sa note de bas de tableau", "Date d''arrêté doublée : numérique en page 1, en toutes lettres en page 2 — contrôle de cohérence interne gratuit"], "token_periodicite": "Cumul des opérations pour l''année"}'::jsonb, '3', '{"pieges": ["Ce gabarit expose un ID DE TEMPLATE NATIF (TYPE_MODELE=66) : quand il est présent, il court-circuite le matching en couches. Signature parfaite.", "Mise en page Apache FOP en positionnement absolu : espacements extrêmes en -layout. Préférer une extraction par positions (bbox) au découpage par largeur fixe.", "La ligne « FONDS GENERAL (1) » porte « -- » à la place des valeurs numériques mais garde une Valorisation : cas particulier à isoler.", "Noms de supports repliés sur 2 lignes, ISIN et chiffres sur la première.", "« Gestion libre » porte le total du groupe SUR la ligne du libellé : ce n''est pas une ligne de support.", "En-têtes empilés sur 2 lignes (« Montant brut » / « des versements ») : reconstruire.", "La ligne de total « Valeur du contrat au [date] [montant] » n''a pas de séparateur net : la détecter comme total.", "Le bloc XML technique peut être COUPÉ en fin de ligne physique : un parseur de balises naïf casse. Le filtrer du contenu, le garder pour la signature.", "Artefact d''encodage ponctuel observé sur un caractère accentué : prévoir un remplacement UTF-8.", "Le tableau des Garanties (page 3) reprend les mêmes supports avec un jeu de colonnes RÉDUIT : ne pas le confondre avec le tableau Situation.", "Une variante « Personnes Physiques » du même produit existe : bloc Souscripteur différent, ne pas présumer l''identité des variantes."], "ancrage_tableaux": ["Extraction par positions recommandée plutôt que par largeur fixe.", "Distinguer les deux tableaux par leur jeu de colonnes, pas par leur nombre."], "format_numerique": {"milliers": "espace insécable", "decimal": "virgule", "devise": "€ en suffixe"}}'::jsonb, '{"perf_par_ligne": "non", "forme": "Aucune performance par ligne, ni en % ni en €. Seule la valorisation est publiée. Le comblement par une source tierce est un choix EXPLICITE et tracé (O12), jamais un silence.", "horizon": null}'::jsonb, 'Σ des valorisations des lignes, FONDS GENERAL inclus = « Valeur du contrat au [date] ». Cohérence de la date numérique (p.1) avec la date en toutes lettres (p.2).', true, 'seed', 'high') ON CONFLICT (emetteur_code, gabarit, periodicite) DO UPDATE SET template_id_natif=EXCLUDED.template_id_natif, signature=EXCLUDED.signature, n_pages_indicatif=EXCLUDED.n_pages_indicatif, extraction_hints=EXCLUDED.extraction_hints, champs_publies=EXCLUDED.champs_publies, invariant_controle=EXCLUDED.invariant_controle, emetteur_lisible=EXCLUDED.emetteur_lisible, confiance=EXCLUDED.confiance, version=gabarits.version+1;
